  addr mod 8 = 0 /\ size mod 8 = 0 /\ 8 <= size /\ size / 8 < 2^38 ->
  0 <= v < 256 ->
  app_rng addr (addr + size) ->
  rw_cells asegs m (sh addr) [CB (Z.to_nat (size / 8)) junk] ->
  stk asegs m lo (bv_unsigned sp) ->
  lo + 64 <= bv_unsigned sp ->
  AHI_LO <= lo ->
